import ast,hashlib,json,pathlib,subprocess
root=pathlib.Path('/workspace'); p=json.loads((root/'proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
def check(v,s):
 if 'const' in s: assert v==s['const']
 if 'enum' in s: assert v in s['enum']
 if s.get('type')=='object':
  assert isinstance(v,dict) and set(s.get('required',[]))<=set(v)
  if s.get('additionalProperties') is False: assert set(v)<=set(s['properties'])
  for k,x in v.items():
   if k in s.get('properties',{}): check(x,s['properties'][k])
 if s.get('type')=='array':
  assert isinstance(v,list) and len(v)>=s.get('minItems',0)
  for x in v: check(x,s.get('items',{}))
 if s.get('type')=='string': assert isinstance(v,str) and len(v)>=s.get('minLength',0)
check(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
parent=ast.parse((root/'candidate.py').read_text())
pm={n.name:n for n in next(n for n in parent.body if isinstance(n,ast.ClassDef)).body if isinstance(n,ast.FunctionDef)}
forms=[]
for v in p['variants']:
 path=root/v['file']; t=ast.parse(path.read_text());compile(t,str(path),'exec')
 cfg=next(n for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert ast.literal_eval(cfg.value)==v['config']
 assert hashlib.sha256(path.read_bytes()).hexdigest() in v['note']
 assert hashlib.sha256(json.dumps(v['config'],sort_keys=True,separators=(',',':')).encode()).hexdigest() in v['note']
 m={n.name:n for n in next(n for n in t.body if isinstance(n,ast.ClassDef)).body if isinstance(n,ast.FunctionDef)}
 for name in set(pm)-{'__init__','forward','diagnostics'}: assert ast.dump(m[name])==ast.dump(pm[name])
 assert [ast.dump(n) for n in m['__init__'].body[:len(pm['__init__'].body)]]==[ast.dump(n) for n in pm['__init__'].body]
 cfg.value=ast.Constant(value='CONFIG');forms.append(ast.dump(t))
assert len(set(forms))==1
assert hashlib.sha256((root/'candidate.py').read_bytes()).hexdigest()=='5b4a04b15d711699b21b3b8d35db19104f445b211adf394ee287d9c45b47c2b3'
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
assert len(p['variants'])==4 and any(v['role']=='candidate' for v in p['variants'])
assert r['context']['remaining_seconds']>4*r['context']['protocol']['trial_cap_seconds']+24000
print(json.dumps({'proposal':'ready','schema_syntax_configs_hashes':'pass','four_factorial_modules':'pass','parent_and_baseline_unchanged':'pass','source_diagnostics_count':64,'authorized_phase':r['phase'],'local_training_runs':0,'host_outcomes':'pending'},indent=2))
PY"

